// Procesa TODOS los items que llegaron (uno por post pendiente), no solo el primero
const items = $input.all();
const result = [];
for (const item of items) {
  const p = item.json;
  if (p && p.id) {
    result.push({ json: p });
  } else if (p) {
    const posts = Array.isArray(p) ? p : (p.data || []);
    for (const post of posts) result.push({ json: post });
  }
}
return result;

const items = $input.all();
const config = $('⚙️ Config Distribution').item.json;
const tokens = $('🏢 Aplicar Tokens Empresa').item.json;
const webhookBody = $('🌐 Webhook: Publicar Post').item?.json?.body || {};

return items.map(item => {
  const p = item.json;
  const f = p.fields || p;

  const post_id        = p.id || p.record_id || '';
  const copy_facebook  = f.copy_facebook  || f.Post_Facebook_EN || '';
  const copy_instagram = f.copy_instagram || f.Post_Instagram_EN || '';
  const imagen_url     = f.imagen_url     || f.imagen || '';
  const video_url      = f.video_url      || p.video_url || '';
  const platform       = f.platform || p.platform || 'Facebook';
  const content_type   = webhookBody.content_type || f.content_type || p.content_type || 'post';

  const FB_ACCESS_TOKEN = tokens.FB_ACCESS_TOKEN || p.access_token || '';
  const FB_PAGE_ID = p.fb_page_id || p.page_id || config.FB_PAGE_ID || '';
  const IG_USER_ID = p.instagram_account_id || tokens.IG_USER_ID || '';

  return { json: {
    post_id, copy_facebook, copy_instagram, imagen_url, video_url,
    has_image: !!imagen_url, has_video: !!video_url, platform, content_type,
    FB_ACCESS_TOKEN, FB_PAGE_ID, IG_USER_ID
  } };
});

const postId = $('🔧 Preparar Datos Post').item?.json?.post_id || 'desconocido';
const g54Status = $('✅ G54: Estado → Publicado').item?.json?.status || 'sin respuesta';
const ts = new Date().toLocaleString('es-CR', {timeZone:'America/New_York'});

return [{
  json: {
    mensaje: `Post ${postId} publicado en FB/IG y marcado en G54 como publicado.`,
    timestamp_miami: ts,
    g54_response: g54Status,
  }
}];

const config = $('⚙️ Config Distribution').item.json;
const pageData = $('🔑 Obtener Tokens Página (G54)').item.json;
const igData = $('📷 Obtener IG User ID (Meta)').item.json;

const ig_user_id = igData?.instagram_business_account?.id || pageData.ig_user_id || '';

let fb_access_token = pageData.fb_access_token || config.FB_ACCESS_TOKEN || '';
try {
  const exchanged = $('🔑 Intercambiar Page Token (FB)').item.json;
  if (exchanged && exchanged.access_token) fb_access_token = exchanged.access_token;
} catch (e) {}

return [{json: {
  ...config,
  FB_ACCESS_TOKEN: fb_access_token,
  IG_USER_ID: ig_user_id
}}];

const webhook = $('🌐 Webhook: Publicar Post').item?.json?.body || {};
const postId = webhook.post_id;
const posts = $('📥 Obtener Posts a Publicar (G54)').item.json.data || [];
const filtered = postId ? posts.filter(p => String(p.id) === String(postId)) : posts;
if (!filtered.length) return [];
return filtered.map(p => ({ json: p }));

const originales = $("🔧 Preparar Datos Post").all();
const exchanges = $input.all();
const resultados = [];
for (let i = 0; i < originales.length; i++) {
  const original = originales[i].json;
  const exch = exchanges[i] ? exchanges[i].json : {};
  const exchangedToken = (exch && exch.access_token) ? exch.access_token : "";
  resultados.push({ json: { ...original, FB_ACCESS_TOKEN: exchangedToken || original.FB_ACCESS_TOKEN } });
}
return resultados;

const containerId = $input.first().json.id;
const accessToken = $('🔧 Preparar Datos Post').item.json.FB_ACCESS_TOKEN;
const maxAttempts = 15;
const delayMs = 10000;

for (let i = 0; i < maxAttempts; i++) {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://graph.facebook.com/v19.0/${containerId}`,
    qs: { fields: 'status_code', access_token: accessToken },
    json: true
  });
  if (res.status_code === 'FINISHED') {
    return [{ json: { id: containerId, ready: true, status_code: res.status_code } }];
  }
  if (res.status_code === 'ERROR' || res.status_code === 'EXPIRED') {
    throw new Error('IG Reel container failed processing: ' + res.status_code);
  }
  if (i < maxAttempts - 1) {
    await new Promise(resolve => setTimeout(resolve, delayMs));
  }
}
throw new Error('IG Reel container did not finish processing in time (timeout tras ' + (maxAttempts * delayMs / 1000) + 's)');

let errorMessage = 'Fallo desconocido al publicar';
try {
  if ($('🔀 Rutear: Plataforma + Imagen').isExecuted && $json.platform === 'Instagram' && !$json.imagen_url) {
    errorMessage = 'Instagram requiere imagen: el post no tiene imagen_url';
  } else if ($('⚠️ IG: Skip (container falló)').isExecuted) {
    const err = $json.error || {};
    const detail = err.message || (err.error && err.error.message) || JSON.stringify(err) || 'sin detalle';
    errorMessage = 'Instagram: falló la creación del container — ' + detail;
  } else if ($('📘 FB: Publicar Solo Texto').isExecuted) {
    const err = $json.error || {};
    const detail = err.message || (err.error && err.error.message) || JSON.stringify(err) || 'sin detalle';
    errorMessage = 'Facebook: falló la publicación — ' + detail;
  }
} catch (e) {
  errorMessage = 'Error al construir el mensaje de fallo: ' + e.message;
}
return [{ json: { errorMessage } }];

